package local.skyfamily;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.io.*;import java.util.*;
public class BooksActivity extends WorkspaceActivity {
 BookReader reader;int shelfPage=0;
 @Override void page(String title){if(reader!=null){reader.store();reader=null;}super.page(title);}
 @Override void pick(boolean media){if(media)super.pick(true);else bookshelf();}
 @Override void drawing(boolean colouring){super.drawing(colouring);artFull=true;renderStudio();}
 @Override void tile(String title,String subtitle,String mark,int color,Runnable action){if(title.equals("Books & school")){title="Bookshelf";subtitle="Covers, chapters and reading progress";}super.tile(title,subtitle,mark,color,action);}
 File bookDir(){File dir=new File(getFilesDir(),"books");dir.mkdirs();return dir;}
 JSONArray index(){try{return new JSONArray(get("books.index").isEmpty()?"[]":get("books.index"));}catch(Exception e){return new JSONArray();}}
 void importBook(){Intent intent=new Intent(Intent.ACTION_GET_CONTENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");if(Build.VERSION.SDK_INT>=19)intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/epub+zip","text/plain"});try{startActivityForResult(Intent.createChooser(intent,"Import EPUB or UTF-8 text book"),701);}catch(Exception e){toast("Install a file picker first");}}
 @Override protected void onActivityResult(int req,int result,Intent data){if(req!=701){super.onActivityResult(req,result,data);return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String found="Book";try(Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())found=cursor.getString(0);}catch(Exception ignored){}final String name=found==null?"Book":found;String mime=getContentResolver().getType(uri);final String ext=name.toLowerCase(Locale.US).endsWith(".epub")||"application/epub+zip".equals(mime)?".epub":name.toLowerCase(Locale.US).endsWith(".txt")||"text/plain".equals(mime)?".txt":"";if(ext.isEmpty()){toast("Import EPUB or UTF-8 TXT here. Use Open school document for PDF and other formats.");return;}int stamp=revision;text("Importing "+name+"...");work(()->{File dir=bookDir();File[] existing=dir.listFiles();long used=0;if(existing!=null)for(File f:existing)used+=f.length();if(index().length()>=100||used>250000000L)throw new IOException("Bookshelf limit reached (100 books / about 250 MB)");String id=UUID.randomUUID().toString();File target=new File(dir,id+ext);boolean success=false;try{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(target)){if(in==null)throw new IOException("Cannot read selected file");byte[] b=new byte[16384];long size=0;int n;while((n=in.read(b))!=-1){size+=n;if(size>50000000L||used+size>250000000L)throw new IOException("Book exceeds import size limit");out.write(b,0,n);}}BookData parsed=BookData.load(target);String title=parsed.title.equals("Book")?(name.lastIndexOf('.')>0?name.substring(0,name.lastIndexOf('.')):name):parsed.title;JSONObject record=new JSONObject().put("id",id).put("file",target.getName()).put("title",title).put("author",parsed.author).put("format",ext.substring(1).toUpperCase(Locale.US));if(parsed.cover!=null){BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(parsed.cover,0,parsed.cover.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>240||options.outHeight/options.inSampleSize>320)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap cover=BitmapFactory.decodeByteArray(parsed.cover,0,parsed.cover.length,options);if(cover!=null){try(FileOutputStream out=new FileOutputStream(new File(dir,id+".png"))){cover.compress(Bitmap.CompressFormat.PNG,100,out);}cover.recycle();}}success=true;ui.post(()->{JSONArray all=index();all.put(record);save("books.index",all.toString());toast("Book imported");if(stamp==revision){shelfPage=0;bookshelf();}});}finally{if(!success){target.delete();new File(dir,id+".png").delete();}}});}
 void bookshelf(){page("Bookshelf");button("Import EPUB / text book",()->importBook());button("Open PDF / other school document in installed reader",()->super.pick(false));JSONArray all=index();ArrayList<JSONObject> books=new ArrayList<>();for(int i=0;i<all.length();i++)if(all.optJSONObject(i)!=null)books.add(all.optJSONObject(i));Collections.sort(books,(a,b)->Long.compare(prefs.getLong("book."+b.optString("id")+".last",0),prefs.getLong("book."+a.optString("id")+".last",0)));String last=get("books.last");for(JSONObject b:books)if(b.optString("id").equals(last)){button("Continue reading / "+b.optString("title"),()->openBook(b));break;}EditText search=input("Search title or author","");LinearLayout shelf=new LinearLayout(this);shelf.setOrientation(1);body.addView(shelf);Runnable render=()->{shelf.removeAllViews();ArrayList<JSONObject> filtered=new ArrayList<>();String q=search.getText().toString().toLowerCase(Locale.getDefault());for(JSONObject b:books)if((b.optString("title")+" "+b.optString("author")).toLowerCase(Locale.getDefault()).contains(q))filtered.add(b);int first=Math.min(shelfPage*20,Math.max(0,(filtered.size()-1)/20*20));int columns=getResources().getConfiguration().screenWidthDp>=900?3:2;LinearLayout row=null;int count=0;for(int i=first;i<Math.min(first+20,filtered.size());i++){JSONObject b=filtered.get(i);if(count%columns==0){row=new LinearLayout(this);shelf.addView(row);}LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(press(surface));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(280),1);cp.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(card,cp);File coverFile=new File(bookDir(),b.optString("id")+".png");if(coverFile.exists()){ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.setImageBitmap(BitmapFactory.decodeFile(coverFile.getPath()));card.addView(cover,new LinearLayout.LayoutParams(-1,dp(130)));}else{TextView cover=new TextView(this);String title=b.optString("title","Book");cover.setText(title.substring(0,Math.min(2,title.length())).toUpperCase(Locale.getDefault())+"\n"+b.optString("format"));cover.setTextColor(accent);cover.setTextSize(26);cover.setGravity(Gravity.CENTER);cover.setBackground(shape(0xff183d50,edge,12));card.addView(cover,new LinearLayout.LayoutParams(-1,dp(130)));}TextView title=new TextView(this);title.setText(b.optString("title"));title.setTextSize(18);title.setTextColor(fg);title.setMaxLines(2);card.addView(title);TextView author=new TextView(this);author.setText(b.optString("author"));author.setTextColor(muted);author.setMaxLines(1);card.addView(author);String key="book."+b.optString("id");ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgress(prefs.getInt(key+".percent",0));card.addView(progress,new LinearLayout.LayoutParams(-1,dp(14)));TextView detail=new TextView(this);detail.setText(get(key+".label").isEmpty()?"Not started":get(key+".label"));detail.setTextColor(accent);detail.setTextSize(12);detail.setMaxLines(2);card.addView(detail);card.setOnClickListener(v->openBook(b));card.setOnLongClickListener(v->{bookOptions(b);return true;});count++;}if(row!=null&&count%columns!=0)for(int i=count%columns;i<columns;i++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));if(filtered.isEmpty()){TextView empty=new TextView(this);empty.setText("No books yet / import EPUB or TXT to get started.");empty.setTextColor(muted);shelf.addView(empty);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int start,int before,int count){shelfPage=0;render.run();}public void afterTextChanged(Editable e){}});render.run();button("Previous shelf page",()->{shelfPage=Math.max(0,shelfPage-1);render.run();});button("Next shelf page",()->{shelfPage++;render.run();});text("Long-press a book to remove it. EPUB covers are used when available; TXT and coverless books get a title tile.");}
 void bookOptions(JSONObject book){new android.app.AlertDialog.Builder(this).setTitle(book.optString("title")).setMessage("Remove this imported copy and its saved progress? The original file is not changed.").setPositiveButton("Remove",(d,w)->{String id=book.optString("id");new File(bookDir(),book.optString("file")).delete();new File(bookDir(),id+".png").delete();JSONArray next=new JSONArray(),old=index();for(int i=0;i<old.length();i++){JSONObject b=old.optJSONObject(i);if(b!=null&&!b.optString("id").equals(id))next.put(b);}save("books.index",next.toString());android.content.SharedPreferences.Editor editor=prefs.edit();for(String key:prefs.getAll().keySet())if(key.startsWith("book."+id+"."))editor.remove(key);editor.apply();bookshelf();}).setNegativeButton("Cancel",null).show();}
 void openBook(JSONObject book){page("Opening book");text(book.optString("title"));int stamp=revision;work(()->{BookData data=BookData.load(new File(bookDir(),book.getString("file")));ui.post(()->{if(stamp!=revision)return;page(book.optString("title"));reader=new BookReader(this,book,data);setContentView(reader);immersive();});});}
 @Override public void onBackPressed(){if(reader!=null)bookshelf();else super.onBackPressed();}
 @Override protected void onPause(){if(reader!=null)reader.store();super.onPause();}
}
